  const MINT_AN = /[?&]mint=an\b/.test(location.search);   // nur lokal: lässt auch den Bot die Anfrage stellen (Prüfwerkzeuge mit Attrappe); auf einem echten Host ohne Wirkung
  const MINT_MS = 10000;   // Zeitgrenze der Anfrage: 10 s, danach Zustand „netz“
