    cap: { fuss: ['Heute sind alle Codes vergeben', 'Alle Codes vergeben'], zeilen: h => ['Heute alle Codes vergeben.', h ? `Neue Codes in etwa ${h}.` : 'Morgen gibt es neue.'] },
    netz: { fuss: ['Keine Verbindung, nochmal versuchen', 'Keine Verbindung'], zeilen: () => ['Keine Verbindung.', 'Probier es nochmal.'] },
