    const zh = SH - rand * 2 - 4, zb = Math.round(zh * 1.42), steg = Math.max(5, zb * 0.05), schritt = zb + steg;
    const loch = schritt / 4, lw = loch * 0.52, lhh = Math.min(rand * 0.5, lw * 0.72);
