      const a0 = ax - aw / 2 - 14, a1 = ax + aw / 2 + 14, bogen = t => [(1 - t) * (1 - t) * a0 + 2 * (1 - t) * t * ax + t * t * a1, (1 - t) * (1 - t) * B + 2 * (1 - t) * t * (B - 250) + t * t * B];
